 async function syncPublicSubject(entry:{code:string;title:string;year:number;semester:number;description?:string;file:string}){
 const response=await fetch('/docs/subjects/'+encodeURIComponent(entry.file),{cache:'no-store'});
 if(!response.ok)throw new Error('Cannot fetch '+entry.file+' (HTTP '+response.status+')');
 const doc=await response.json();
 if(!Array.isArray(doc.units)||!doc.units.length||doc.units.length>100)throw new Error(entry.file+' must contain 1–100 units.');
 const code=entry.code.trim().toUpperCase();
 const {data:existingSubject,error:lookupError}=await sb.from('study_subjects').select('*').eq('code',code).eq('year',entry.year).eq('semester',entry.semester).maybeSingle();
 if(lookupError)throw new Error(lookupError.message);
 let subjectId=existingSubject?.id as string|undefined;
 if(!subjectId){
  const inserted=await sb.from('study_subjects').insert({code,title:entry.title,year:entry.year,semester:entry.semester,description:entry.description||''}).select('id').single();
  if(inserted.error)throw new Error(inserted.error.message);
  subjectId=inserted.data.id;
 }else if(existingSubject.title!==entry.title||existingSubject.description!==(entry.description||'')){
  const updated=await sb.from('study_subjects').update({title:entry.title,description:entry.description||''}).eq('id',subjectId);
  if(updated.error)throw new Error(updated.error.message);
 }
 const {data:existingModules,error:modulesError}=await sb.from('study_modules').select('id,title,position,content_json').eq('subject_id',subjectId);
 if(modulesError)throw new Error(modulesError.message);
 const rows=doc.units.map((u:any,i:number)=>{
  if(!u||typeof u.title!=='string'||!Array.isArray(u.topics))throw new Error('Invalid unit '+(i+1)+' in '+entry.file);
  const blocks:Array<{type:string;text:string}>=[];
  if(typeof u.unit_introduction==='string')blocks.push({type:'paragraph',text:u.unit_introduction});
  for(const t of u.topics){
   if(typeof t.title!=='string')throw new Error('Topic title required in '+entry.file);
   blocks.push({type:'heading',text:(t.topic_number||'')+' '+t.title});
   for(const x of t.objectives||[])if(typeof x==='string')blocks.push({type:'bullet',text:x});
   for(const k of t.key_concepts||[])if(typeof k.concept==='string'&&typeof k.details==='string')blocks.push({type:'heading',text:k.concept},{type:'paragraph',text:k.details});
   for(const x of t.activities||[])if(typeof x.description==='string')blocks.push({type:'paragraph',text:'Activity: '+x.description});
   if(typeof t.summary==='string')blocks.push({type:'paragraph',text:'Summary: '+t.summary});
  }
  if(typeof u.unit_summary==='string')blocks.push({type:'paragraph',text:u.unit_summary});
  return {subject_id:subjectId!,title:'Unit '+(u.unit_number??i+1)+': '+u.title,notes:'',position:i,content_json:{version:1,blocks,source_unit:u,course_document:doc.document||null}};
 });
 for(const row of rows){
  const prior=(existingModules||[]).find(m=>m.title===row.title);
  if(prior){
   if(JSON.stringify(prior.content_json)===JSON.stringify(row.content_json)&&prior.position===row.position)continue;
   const updated=await sb.from('study_modules').update({content_json:row.content_json,position:row.position}).eq('id',prior.id);
   if(updated.error)throw new Error(updated.error.message);
  }else{
   const inserted=await sb.from('study_modules').insert(row);
   if(inserted.error)throw new Error(inserted.error.message);
  }
 }
}
