 async function uploadMaterial(file:File,targetModuleId=moduleId){if(!targetModuleId)return;if(file.size>20*1024*1024){setError('File must be under 20 MB');return}const allowed=['application/pdf','image/png','image/jpeg','text/plain'];if(!allowed.includes(file.type)){setError('Only PDF, PNG, JPEG and TXT files are supported');return}setBusy(true);setError('');const path=targetModuleId+'/'+crypto.randomUUID()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const uploaded=await sb.storage.from(storage).upload(path,file,{upsert:false});if(uploaded.error){setError(uploaded.error.message);setBusy(false);return}const inserted=await sb.from('study_resources').insert({module_id:targetModuleId,title:file.name,storage_path:path,mime_type:file.type});if(inserted.error){await sb.storage.from(storage).remove([path]);setError(inserted.error.message)}else if(user)await refresh(user);setBusy(false)}
